const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    // The question mentions the "Norwegian Sea" but the coordinates are in the Labrador Sea, off Canada.
    // The analysis will proceed using the explicit coordinates provided.
    const point1 = ee.Geometry.Point([-58.944881, 50.282684]);
    const point2 = ee.Geometry.Point([-54.128047, 50.415337]);
    const dateStart = '2019-09-01';
    const dateEnd = '2019-09-02'; // A 1-day window for a specific date.

    // 2. Data Acquisition & Processing Function
    // Use Sentinel-2 Surface Reflectance for water color analysis.
    const s2Collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
        .filterDate(dateStart, dateEnd);

    // Function to mask clouds using the Scene Classification Layer (SCL).
    // Keeps water (6), saturated/defective (1), dark areas (2), vegetation (4), not vegetated (5), and unclassified (7).
    // Masks clouds (8, 9, 10), cloud shadows (3), and snow (11).
    function maskS2Clouds(image) {
        const scl = image.select('SCL');
        const keepMask = scl.eq(6).or(scl.eq(1)).or(scl.eq(2)).or(scl.eq(4)).or(scl.eq(5)).or(scl.eq(7));
        return image.updateMask(keepMask);
    }

    // Function to process a point: find the best image and extract true color intensity.
    function getTrueColorIntensity(point, label) {
        const filtered = s2Collection.filterBounds(point);
        const image = filtered.map(maskS2Clouds).mosaic();

        // Check for valid pixels at the point after cloud masking.
        const pixelCount = image.select('B2').reduceRegion({
            reducer: ee.Reducer.count(),
            geometry: point.buffer(10), // Use a small buffer to ensure pixel capture
            scale: 10,
            maxPixels: 1
        }).get('B2');

        if (ee.Algorithms.IsEqual(pixelCount, 0).getInfo()) {
            return {
                intensity: null,
                count: 0
            };
        }

        // Calculate average intensity of RGB bands to represent "milkiness" or brightness.
        const intensityReducer = ee.Reducer.mean();
        const meanDict = image.select(['B4', 'B3', 'B2']).reduceRegion({
            reducer: intensityReducer,
            geometry: point,
            scale: 10,
            maxPixels: 1
        });

        const r = ee.Number(meanDict.get('B4'));
        const g = ee.Number(meanDict.get('B3'));
        const b = ee.Number(meanDict.get('B2'));
        const intensity = r.add(g).add(b).divide(3);

        return {
            intensity: intensity.getInfo(),
            count: 1
        };
    }

    // 3. Calculation & Validation
    if (s2Collection.size().getInfo() === 0) {
        console.log(`Evidence: No Sentinel-2 images found for ${dateStart}.`);
        console.log("A: Yes");
        return;
    }

    const result1 = getTrueColorIntensity(point1, "Point 1");
    const result2 = getTrueColorIntensity(point2, "Point 2");

    const intensity1 = result1.intensity;
    const intensity2 = result2.intensity;

    console.log(`Evidence: Point 1 (more milky?) True Color Intensity: ${intensity1 ? intensity1.toFixed(2) : 'N/A'}, Valid Pixels: ${result1.count}`);
    console.log(`Evidence: Point 2 (less milky?) True Color Intensity: ${intensity2 ? intensity2.toFixed(2) : 'N/A'}, Valid Pixels: ${result2.count}`);

    if (result1.count === 0 || result2.count === 0) {
        console.log("Reason: No valid (cloud-free) pixels found at one or both locations.");
        console.log("C2");
        return;
    }

    if (intensity1 === null || intensity2 === null) {
        console.log("Reason: Failed to calculate intensity value for one or both points.");
        console.log("C3");
        return;
    }

    // 4. Final Answer
    if (intensity1 > intensity2) {
        console.log("A: Yes");
    } else {
        console.log("B: No");
    }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
  console.error(err);
  console.log("D");
});
